-- Source and independent-solution verification; no historical scores changed.
-- Before-images are retained in audit_log; rows in active exams are deferred.
DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "489ec344-ab0c-68f5-f64b-f13fc2627407", "before": {"stem": "In the scatter plot below, at what x-value is the difference between the line\nof best fit and the actual point the greatest?", "choices": [{"key": "A", "text": "9"}, {"key": "B", "text": "5"}, {"key": "C", "text": "14"}, {"key": "D", "text": "3"}], "correct": "A", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p29-q145", "source": "/workspace/scratch/e379d1a7362b/audit-sources/DOC-20260623-WA0016_260909_203219.pdf; physical page 29", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "At which listed x-value is the absolute vertical difference between the observed point and the line of best fit greatest?", "choices": [{"key": "A", "text": "9"}, {"key": "B", "text": "5"}, {"key": "C", "text": "14"}, {"key": "D", "text": "3"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "Compare each point’s vertical distance from the dashed fitted line. At x = 9 the observed point is near y = 28 and the fitted value is near 21.5, a difference of about 6.5. The points at x = 3, 5, and 14 lie much closer to the line. Thus the largest absolute residual is at x = 9.", "correct": "A"}, {"id": "a20cd2fb-626f-be33-da24-e909075b6bb5", "before": {"stem": "From the World Cup goals chart below, Mₑ is the median and Mₒ is the mode.\nFind Mₑ − Mₒ.", "choices": [{"key": "A", "text": "0"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "3"}], "correct": "A", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p44-q201", "source": "/workspace/scratch/e379d1a7362b/audit-sources/DOC-20260623-WA0016_260909_203219.pdf; physical page 44", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "The chart lists goals scored by seven players. If Mₑ is the median number of goals and Mₒ is the mode, what is Mₑ − Mₒ?", "choices": [{"key": "A", "text": "0"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "3"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "The goal counts in order are 3, 4, 4, 4, 6, 6, 8. The fourth value, 4, is the median. The most frequent value is also 4, so the mode is 4. Their difference is 4 − 4 = 0.", "correct": "A"}, {"id": "e4b74058-7d91-66e0-2dae-642c1dc9c44e", "before": {"stem": "Q48. From the World Cup goals chart below, Mₑ is the median and Mₒ is the mode.\n Find Mₑ − Mₒ.", "choices": [{"key": "A", "text": "0"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "3 [Statistics — Mean [Jan. 2026]] Ghoneem"}], "correct": "A", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00195", "source": "/workspace/scratch/e379d1a7362b/audit-sources/DOC-20260623-WA0016_260909_203219.pdf; physical page 44", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "The chart lists goals scored by seven players. If Mₑ is the median number of goals and Mₒ is the mode, what is Mₑ − Mₒ?", "choices": [{"key": "A", "text": "0"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "3"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "The goal counts in order are 3, 4, 4, 4, 6, 6, 8. The fourth value, 4, is the median. The most frequent value is also 4, so the mode is 4. Their difference is 4 − 4 = 0.", "correct": "A"}, {"id": "de453fc9-53d3-b40a-d587-8b44eb5cb17a", "before": {"stem": "1.\n Find the equation of the line in the xy-plane above.", "choices": [{"key": "A", "text": "y = 4x+15"}, {"key": "B", "text": "y = 16x+15"}, {"key": "C", "text": "y = 4x-15"}, {"key": "D", "text": "y = -4x+15"}], "correct": "A", "explanation": "The plotted line passes through (0,15) and (10,55), giving slope (55 - 15)/10 = 4 and y-intercept 15: y = 4x + 15."}, "source_question_id": "est1_dec_2025-q00001", "source": "/workspace/scratch/e379d1a7362b/audit-sources/December 2025 est 1 math_260716_152922.pdf; physical page 1", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "Which equation represents the line shown in the xy-plane?", "choices": [{"key": "A", "text": "y = 4x + 15"}, {"key": "B", "text": "y = 16x + 15"}, {"key": "C", "text": "y = 4x − 15"}, {"key": "D", "text": "y = −4x + 15"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "The graph crosses the y-axis at 15 and passes through (10,55). Its slope is (55 − 15)/(10 − 0) = 4. Thus its equation is y = 4x + 15.", "correct": "A"}, {"id": "aa432aee-ed98-525d-16f3-bba2ef9d15cb", "before": {"stem": "17.\n The scatter plot shows the relationship between weight (x) in kilograms and height (y) in centimeters for a group\n of students.\n Which of the following equations represents the line of best fit above?", "choices": [{"key": "A", "text": "y=3x-3.2"}, {"key": "B", "text": "y=3x+2.2"}, {"key": "C", "text": "y=4.3x+53.2"}, {"key": "D", "text": "y=4.3x-5.2"}], "correct": "B", "explanation": "The line of best fit rises about 3 y-units per 1 x-unit and has a positive intercept near 2.2. Among the choices, y = 3x + 2.2 fits the graph."}, "source_question_id": "est1_dec_2025-q00016", "source": "/workspace/scratch/e379d1a7362b/audit-sources/December 2025 est 1 math_260716_152922.pdf; physical page 5", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "The scatterplot relates weight x in kilograms to height y in centimeters. Which listed equation best approximates the displayed line of best fit?", "choices": [{"key": "A", "text": "y = 3x − 3.2"}, {"key": "B", "text": "y = 3x + 2.2"}, {"key": "C", "text": "y = 4.3x + 53.2"}, {"key": "D", "text": "y = 4.3x − 5.2"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "The fitted line rises by about 3 units of y per unit of x and has a small positive y-intercept. Among the options, y = 3x + 2.2 best matches both features. A has a negative intercept; C has an intercept far above the plotted scale; D is too steep and has a negative intercept.", "correct": "B"}, {"id": "be5d603a-ac3a-5b80-b210-338925e28fb6", "before": {"stem": "Which two transformations can be used to obtain the graph of g(x) = −√(x − c) from the graph of f(x) = √x if c > 0 ?", "choices": [{"key": "A", "text": "A translation to the right c units followed by a reflection across the x-axis"}, {"key": "B", "text": "A translation to the left c units followed by a reflection across the x-axis"}, {"key": "C", "text": "A translation to the right c units followed by a reflection across the y-axis"}, {"key": "D", "text": "A translation to the left c units followed by a reflection across the y-axis"}], "correct": "A", "explanation": "Source-keyed answer from moh.md (MA-17)."}, "source_question_id": "MA-17", "source": "Kimi supplied transcription, moh.md MA-17; complete formulas in stem", "review_note": "Structural flag is a false positive: both functions are explicitly defined, so no separate graph is needed. Independently checked both transformations.", "release": true, "fields": {}, "explanation": "Replacing x by x − c translates y = √x to the right by c units. Negating the entire output reflects that translated graph across the x-axis, giving y = −√(x − c). Thus A is correct.", "correct": "A"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260928' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260928','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260928','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-28-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-28-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-28-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260928'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260928')) AS result;
